-- ════════════════════════════════════════════════════════════
-- Recruitment — clients, jobs, candidates, pipeline
-- The TA workspace: client accounts, requisitions, the candidate bank, applications moving through stages, interviews and placements.
-- Generated by scripts/db/generate.ts — edit config.ts / types.ts, then re-run.
-- ════════════════════════════════════════════════════════════

-- Backs the "clients" collection (type Client).
create table if not exists crm.clients (
  id                   text not null,
  org_id               text not null,
  company_name         text,
  industry             text,
  website              text,
  contact_person       text,
  contact_email        text,
  contact_phone        text,
  address              text,
  status               text, -- ACTIVE | PROSPECT | ONBOARDING | PAUSED | CHURNED
  agreement_url        text,
  commission_rate      numeric,
  credit_days          numeric,
  account_manager_id   text,
  estimated_value      text,
  notes                text,
  billing              jsonb,
  credit_hold          boolean,
  created_at           timestamptz,
  updated_at           timestamptz,
  _extra               jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position            double precision not null default 0, -- list order the app expects
  primary key (id)
);

-- Backs the "clientLeads" collection (type ClientLead).
create table if not exists crm.client_leads (
  id                          text not null,
