  assigned_to_name            text,
  assigned_to_id              text,
  stage                       text, -- NEW | CONTACTED | QUALIFIED | MEETING | PROPOSAL | NEGOTIATION | CONVERTED | LOST
  expected_positions          numeric,
  expected_annual_value_lpa   numeric,
  priority                    text, -- LOW | MEDIUM | HIGH | URGENT
  next_follow_up_date         text,
  notes                       text,
  converted_client_id         text,
  created_at                  timestamptz,
  updated_at                  timestamptz,
  _extra                      jsonb not null default '{}'::jsonb, -- values that don't fit a typed column (kept losslessly)
  _position                   double precision not null default 0, -- list order the app expects
  primary key (id)
);

